statement:
One table holds a medal count:

- `Olympic(country, gold_medals, silver_medals, bronze_medals)`: one row per country; `country` is unique, and each column counts the medals of that kind the country won.

Return the whole table, all four columns in their original order, sorted like an Olympic medal table:

1. more `gold_medals` first;
2. on equal gold, more `silver_medals` first;
3. on equal gold and silver, more `bronze_medals` first;
4. on equal counts of all three, by `country` name in ascending alphabetical order.

The row order is part of the answer.

validator:
function validate(input) {
  const [{ Olympic = [] }] = input;
  const names = new Set();
  for (const [country, gold, silver, bronze] of Olympic) {
    if (country === null || gold === null || silver === null || bronze === null) return 'Every value is required.';
    const key = String(country).toLowerCase();
    if (names.has(key)) return `Country ${country} appears twice.`;
    names.add(key);
    if (gold < 0 || silver < 0 || bronze < 0) return 'Medal counts cannot be negative.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const Olympic = [];
  if (size === 'small') {
    // Medal counts from 0 to 2 make ties on gold, on silver and on all three columns common.
    const pool = ['China', 'USA', 'Israel', 'Egypt', 'South Sudan', 'Brazil', 'Kenya', 'Japan', 'Chad', 'Norway', 'Peru', 'Italy'];
    for (let i = pool.length - 1; i > 0; i--) { const j = pick(i + 1); [pool[i], pool[j]] = [pool[j], pool[i]]; }
    const count = pick(9);
    for (let i = 0; i < count; i++) Olympic.push([pool[i], pick(3), pick(3), pick(3)]);
  } else {
    // Distinct invented names built from syllables; small medal ranges keep many full ties.
    const parts = ['ka', 'lo', 'mi', 'ra', 'su', 'te', 'vo', 'ne', 'bi', 'do', 'fa', 'gu', 'ha', 'ji', 'po', 'ze'];
    const seen = new Set();
    while (Olympic.length < 2000) {
      let name = '';
      const length = 2 + pick(3);
      for (let k = 0; k < length; k++) name += parts[pick(parts.length)];
      name = name[0].toUpperCase() + name.slice(1);
      if (seen.has(name)) continue;
      seen.add(name);
      Olympic.push([name, pick(8), pick(6), pick(5)]);
    }
  }
  return [{ Olympic }];
}
